"""Integrate completed FPR experiments into new Array manuscript sources.

No classifier loading, fitting, prediction or benchmark takes place here.
Every new numerical table is derived from checksum-verified saved artifacts.
"""
from pathlib import Path
import json,hashlib,shutil,re,csv,difflib
ROOT=Path(__file__).resolve().parents[1]
OLD=ROOT/'paper/array_20261105_editorial/elsarticle'
NEW=ROOT/'paper/array_20261105_fpr_update/elsarticle'
OUT=ROOT/'reports/ARRAY_FPR_UPDATE_20261105'
P=ROOT/'runs/PAYLOAD_TARGET_REPAIR_20261105_01';G=ROOT/'runs/SQL_DISAGREEMENT_REPAIR_20261105_01';D=ROOT/'reports/SQL_FPR_REPAIR_20261105'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rows(p):
    with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
def fmt(v,d=4):return '--' if v in ('',None) else f'{float(v):.{d}f}'
def count(v):return '--' if v in ('',None) else str(int(float(v)))
def esc(v):return str(v).replace('&',r'\&').replace('_',r'\_\allowbreak{}').replace('%',r'\%')
METHODS=['decision_tree','random_forest','xgboost','lightgbm','logistic_regression','soft_voting','weighted_voting','stacking']
SHORT=dict(zip(METHODS,['DT','RF','XGB','LGB','LR','Uniform','Weighted','Stacking']))
VIEWS=['syntax_only','tfidf_only','syntax_tfidf']
VN={'syntax_only':'Syntax','tfidf_only':'TF-IDF','syntax_tfidf':'Hybrid'}
FM=['reference','matched_base_availability','matched_base_syntax','matched_base_tfidf','matched_base_hybrid']
FL=dict(zip(FM,['Reference85','+ Availability','+ Syntax','+ TF-IDF','+ Hybrid']))
LEDGER=[]
def table(label,caption,header,data,weights,note,scope='supplement'):
    assert abs(sum(weights)-1)<1e-6 and all(len(row)==len(header) for row in data)
    LEDGER.append(dict(scope=scope,label=label,caption=caption,header=header,rows=data,note=note))
    n=len(header);spec=''.join(r'L{'+f'{w:.8f}'+r'\dimexpr\textwidth-'+str(2*n)+r'\tabcolsep\relax}' for w in weights)
    body='\n'.join(' & '.join(esc(c) for c in row)+r'\\' for row in data)
    return (r'\begin{table}[!htbp]\centering\footnotesize\setlength{\tabcolsep}{3pt}\renewcommand{\arraystretch}{1.10}'+'\n'+r'\caption{'+caption+r'}\label{'+label+'}\n'+r'\begin{tabular}{'+spec+r'}\toprule'+'\n'+' & '.join(r'\textbf{'+esc(c)+'}' for c in header)+r'\\\midrule'+'\n'+body+'\n'+r'\bottomrule\end{tabular}\par\smallskip\begin{minipage}{\linewidth}\footnotesize '+note+r'\end{minipage}\end{table}'+'\n')
def main():
    assert not NEW.exists(),'Keep previous revision; choose a new source folder'
    OUT.mkdir(parents=True,exist_ok=True)
    for folder in (P,G):
        assert sha(folder/'artifacts_sha256.json')==read(folder/'complete.json')['catalog_sha256']
        for r in read(folder/'artifacts_sha256.json'):
            p=folder/r['path'];assert p.stat().st_size==r['bytes'] and sha(p)==r['sha256']
    assert read(D/'verification.json')['status']=='PASS' and read(D/'package_verification.json')['status']=='PASS'
    NEW.mkdir(parents=True)
    for p in OLD.iterdir():
        if p.is_file() and p.suffix in ['.cls','.bst']:shutil.copy2(p,NEW/p.name)
    shutil.copytree(OLD/'figures',NEW/'figures')
    M=rows(P/'metrics.csv');GM=rows(G/'metrics.csv');EF=rows(G/'efficiency_summary.csv');COR=rows(P/'correction_results.csv')
    def metric(k,c,m='weighted_voting'):return next(r for r in M if r['key']==k and r['cohort']==c and r['method']==m)
    def guard(k,c):return next(r for r in GM if r['key']==k and r['cohort']==c)
    maintex=(OLD/'main.tex').read_text(encoding='utf8')
    abstract=r'''We study bounded prior-only endpoint context, prediction-preserving execution and full-probability explanation audits for five-class IoT intrusion detection on Edge-IIoTset. A matched context/ordering ablation isolates a 1.14-point temporal macro-F1 gain from adding ten-second statistics. Packet-private history reduces signature macro-F1 from 97.296\% to 93.769\%, exposing evaluation dependence. Additional benign sources produce 321/760 false alarms (42.24\%) after flag alignment; matched full-training payload interventions leave 310--331. A retrospective RF-disagreement rule with a syntax/character-TF-IDF check removes all 321 observed alarms and retains every label on 10,358 temporal targets. However, RF-only reconciliation matches this result and no evaluated attack activates the rule. Zero observed alarms therefore establish neither safety on new conflict attacks nor a unique payload benefit. Compact execution of the original ensemble preserves tested probabilities and labels and reduces mean replay time by 41.75\% over thirty paired repetitions on one laptop. Exact grouped Shapley audits measure window contributions, donor sensitivity and faithfulness for that predictor. The disagreement rule changes the predictor; execution and explanation-preservation claims do not transfer. One source per class, incomplete benign coverage and adaptive reuse limit all detection findings to observed traces.'''
    maintex=re.sub(r'\\begin\{abstract\}.*?\\end\{abstract\}',lambda _:r'\begin{abstract}'+abstract+r'\end{abstract}',maintex,count=1,flags=re.S)
    anchor='The evidence is exploratory.'
    intro='A later false-alarm investigation compares syntax-based payload features, character TF-IDF and their combination, first as matched refits and then as selective checks of SQL/Normal disagreements. These interventions are diagnostic extensions of RQ1, not an additional claim that weighted voting is the best classifier. A rule designed after observing the benign failures is reported as a new exploratory predictor. Its attack-conflict coverage, resource cost and RF-only ablation are retained separately from the original predictor\'s execution and explanation guarantees.\n\n'
    assert anchor in maintex;maintex=maintex.replace(anchor,intro+anchor,1)
    old='Thus every predictive score in this article is exploratory. No data in this revision qualify as an untouched final test, and the new controls are not used to choose a replacement winner. Supplementary Table S34 records post-observation decisions and their scope.'
    new='Thus every predictive score in this article is exploratory. No data in this revision qualify as an untouched final test. The 3 November controls do not choose a replacement winner; the subsequent 5 November payload and RF-disagreement candidates explicitly respond to observed benign errors. Supplementary Tables S34 and S64 record these decisions and their scope. Neither a fixed threshold nor a stage-local freeze converts the later candidates into prospectively validated methods.'
    assert old in maintex;maintex=maintex.replace(old,new,1)
    old='New revision experiments comprise 70 expert fits; separate smoke fits are not scientific results.'
    assert old in maintex;maintex=maintex.replace(old,'The 3 November controls comprise 70 expert fits. The later payload investigation adds 68 classifier fits, including binary out-of-fold and meta fits, recorded in a separate run; the disagreement-rule evaluation adds none. Separate smoke fits are not scientific results.',1)
    old='No source, model or parameter is selected from its outcomes.'
    assert old in maintex;maintex=maintex.replace(old,'The original stress-test addendum does not select a source, model or parameter from its outcomes; the later repair candidates are explicitly post-observation.',1)
    methods=r'''
\subsection{Post-observation payload and disagreement controls}\label{sec:payload_methods}

After observing the benign failures, we investigate current-packet content without adding a capture or a learner family. All later comparisons use the format-aligned 760 targets and the existing seed-42 temporal A/G/C/V roles. No historical-holdout target enters fitting or evaluation. The original ensemble, weights and compact runtime remain archived. These experiments test a possible response to known errors, not a new unseen final test.

Three content representations are compared: twelve syntax indicators, character TF-IDF, and their concatenation. Syntax counts quotes, Boolean operators, equals signs, numeric tautologies, UNION SELECT, comments, semicolons and SQL keywords, with an isdecimal indicator. TF-IDF uses character 2--5-grams, at most 2,048 terms, lowercase, sublinear term frequency and L2 normalization, implemented with scikit-learn~\cite{r26}. Content is derived from at most 4,096 current bytes. HTTP requests contribute query/form values decoded once; HTTP responses contribute the body. Host headers, cookies, dates, paths and addresses are excluded from the content representation. MQTT contributes its current message body. Missing or unusable content remains explicit; it is not filled with generated text or assigned a Normal label by itself. Table S47 specifies all indicators and extraction choices.

The binary pilot samples 100 unique nonempty Normal contents and 100 unique SQL contents from A, stratified round-robin over available content kinds with seed 20261105. DT, RF, XGB, LGB, LR, uniform/weighted voting and LR stacking are evaluated for each representation. Two group-aware OOF folds supply stacking inputs; fitted preprocessing never sees its validation fold. Binary label 1 is SQL, so DDoS-specific loss weighting is disabled. The weights are inherited unchanged for a controlled comparison, rather than optimized for the binary task. The primary binary test is V content whose lowercase normalized hash does not occur in binary training: 895 Normal and 117 SQL examples. Empty-content and repeated-content outcomes are separate diagnostics. This content-disjoint check does not remove protocol or capture confounding.

The matched five-class experiment refits the existing five experts on all 31,676 A targets, using the same parameter settings, seed and frozen reference weights. Four additions are tested against the original 85-field predictor: availability metadata, syntax, TF-IDF and their combination. Training-only RUS/SMOTE and the original synthetic-cap definition are retained. Four representations require twenty expert fits; the binary OOF/final/meta fits require forty-eight. These fits are complete before this manuscript integration. A content-only alarm correction is also audited: G selects the first recorded threshold with no additional attack-to-Normal errors, C confirms it, and the resulting policies are retained even if they perform poorly on V or the additional targets. This is still adaptive development reuse.

We then define a separate selective predictor. Let $f(x)$ be the original five-class voting posterior, $r(x)$ the RF posterior already computed by its experts, and $b(x)$ a Normal/SQL content posterior. A disagreement is eligible only if $\arg\max f=\mathrm{SQL}$, $\arg\max r=\mathrm{Normal}$ and $r_{\mathrm{Normal}}\geq0.5$. The default 0.5 is not fitted or calibrated. With usable content, a binary SQL decision or a tie retains the original alarm. Otherwise, an eligible row uses the complete RF posterior:
\begin{equation}
h(x)=\begin{cases}r(x),&\mbox{eligible without SQL-or-tie content evidence},\\f(x),&\mbox{otherwise}.\end{cases}\label{eq:disagreement}
\end{equation}
With no usable content, RF evidence remains necessary. Rows outside the SQL/Normal conflict keep $f$. The primary candidate uses the binary syntax+TF-IDF weighted classifier; RF-only reconciliation and all twenty-four binary variants are ablations. The rule was designed after the earlier outcomes were known. G and C contain no eligible disagreements, so they provide no calibration evidence for its conflict region. Equation~\ref{eq:disagreement} changes the predictor, unlike the execution certificate in Eq.~\ref{eq:certificate}. Neither certified-label preservation nor the archived SHAP equivalence result is asserted for $h$.

The conditional implementation computes the five original experts once and parses content only on eligible rows, invoking the binary model only when usable content exists. Native-pipeline timing uses prepared C60/O10 inputs, one numerical-library thread, three warm-ups and ten randomized-order repetitions on V batches of 1,000 and all 760 additional targets. Two cold processes per reference/RF-only/hybrid policy measure inference delta peak RSS, sampled every 1 ms after model load. This is a separate session from the thirty-pair compact replay and excludes raw capture decoding and history construction. Tables S46--S65 retain coverage, all predictors, thresholds, raw timings, RSS and provenance.
'''
    anchor=r'\section{Results and interpretation}';assert anchor in maintex;maintex=maintex.replace(anchor,methods+'\n'+anchor,1)
    old='No new evaluation result is used to retune voting weights or promote a different winner.'
    assert old in maintex;maintex=maintex.replace(old,'These controls do not retune the reference voting weights. The later repair in Section~\\ref{sec:payload_results} is reported as a separate post-observation candidate, not promoted as a universally superior replacement.',1)
    anchor='An independent, fully aligned test with normal and attack sources remains necessary.'
    assert anchor in maintex;maintex=maintex.replace(anchor,anchor+' Section~\\ref{sec:payload_results} examines later repair candidates without removing that requirement.',1)
    mainrows=[]
    for key in FM:
        a=metric(key,'additional');v=metric(key,'V');mainrows.append([FL[key],count(a['false_alarms']),fmt(a['fpr_percent'],2),fmt(v['macro_f1_percent']),count(v['false_negatives'])])
    direct=table('tab:payload_refits','Matched payload refits against the format-aligned seed-42 reference.',['Input / WV','Additional FP','Additional FPR','V macro-F1','V missed attacks'],mainrows,[.28,.15,.18,.20,.19],r'Additional: 760 Normal targets. V: 10,358 targets including 6,498 attacks. FPR and F1 are percentages. All refits use the same A and parameter/weight settings; these are not the earlier 500-row pilot or three-seed means. Missed attacks are attack-to-Normal decisions. All learners and class recalls appear in Tables S50--S52.',scope='main')
    guardrows=[]
    for key,label in [('reference','Reference WV'),('RF_only','RF-only rule'),('syntax_WV','Syntax guard'),('tfidf_WV','TF-IDF guard'),('hybrid_WV','Hybrid guard')]:
        a=guard(key,'additional');v=guard(key,'V');guardrows.append([label,count(a['false_alarms']),fmt(a['fpr_percent'],2),count(v['changed']),count(v['false_negatives'])])
    gt=table('tab:repair','Selective reconciliation on the same observed targets.',['Predictor','Additional FP','Additional FPR','Changed V labels','V missed attacks'],guardrows,[.28,.15,.18,.20,.19],r'FPR is a percentage. All candidates leave the 10,358 V labels identical. There are zero eligible conflicts in G, C or V, including zero attack activations; this table does not establish safety for future conflict attacks. The RF-only rule omits content. Full variant, capture and activation results are in Tables S56--S59.',scope='main')
    costs=[]
    for cohort in ('V','additional'):
        for key,label in [('reference','Reference'),('RF_only','RF-only'),('hybrid_WV','Hybrid')]:
            r=next(z for z in EF if z['cohort']==cohort and z['key']==key);costs.append([cohort+' '+r['n'],label,fmt(r['median_ms'],3),fmt(r['sd_ms'],3),fmt(r['delta_peak_rss_mean_mib'],3)])
    ct=table('tab:repair_cost','Separate native-pipeline cost of the disagreement rule.',['Batch','Policy','Median ms','SD ms','Delta MiB'],costs,[.23,.23,.18,.18,.18],r'Ten latency repetitions after three warm-ups; memory is mean delta peak inference RSS from two cold processes. The input context is already prepared. This is neither the compact implementation nor raw PCAP replay; the 41.75\% replay saving in Table~\ref{tab:runtime} must not be transferred to these policies. Tables S60--S63 retain all measurements.',scope='main')
    results=r'''
\subsection{Payload interventions and selective reconciliation}\label{sec:payload_results}

The false-alarm problem is not primarily resolved by correcting flag text or adding content to every prediction. Of the 321 aligned errors, only 64 have usable current content. The other 257 have TCP payload length zero: 140 ACK, 61 RST, 24 SYN-ACK, 16 SYN and 16 FIN-ACK packets. An absent current payload cannot reveal an injection string, and absence alone does not establish benign behavior. Table S54 records these packets. Extreme context replacements also fail as operational fixes: zeroing context gives 100\% additional FPR, whereas substituting the A-Normal median removes additional alarms but misses 6,498 V attacks. These deliberately nonphysical perturbations diagnose input sensitivity, not causation (Table S55).

Table~\ref{tab:payload_refits} reports the matched full-A intervention. Syntax reduces additional alarms by eleven, from 321 to 310 (42.24\% to 40.79\%), while attack-to-Normal decisions on V rise from two to three. TF-IDF leaves 312 alarms and four missed attacks; the combination increases alarms to 331 (43.55\%) and also misses four attacks. Thus none of the content additions demonstrates the desired alarm reduction without loss of observed sensitivity. Availability metadata alone leaves all 321 additional alarms. These negative results are retained for every learner in Tables S50--S52.
'''+direct+r'''
In the 200-example binary experiment, syntax weighted voting produces 2/895 Normal-to-SQL errors and detects 117/117 SQL examples on the nonempty content-disjoint V subset. TF-IDF produces no false alarms but detects 116/117 SQL examples; the combination produces no false alarms and detects 117/117. Their macro-F1 values are 99.5203\%, 99.7575\% and 100\% (Table S48). These conditional scores do not describe all SQL targets: 1,534 of 1,652 SQL contents in V are empty, and the three weighted binary predictors miss 1,534--1,535 SQL targets when applied to the full 5,512-row Normal/SQL cohort (Table S49). Protocol/source confounding also remains: Normal training comprises fifty MQTT bodies and fifty other TCP contents; all hundred SQL contents are HTTP query values. Hash separation removes identical training content, not these shortcuts. A content-only model is therefore not adopted as the general detector. Correction restricted to usable content recovers 64 original alarms for the three weighted candidates, leaving 257/760 (33.82\%), without changing a V label (Table S53).

The RF-disagreement rule addresses these residual no-content decisions using a different source of evidence: the RF posterior already present in the ensemble. Table~\ref{tab:repair} shows zero alarms among the 760 matched Normal targets for the hybrid rule and for RF-only reconciliation. All 321 changed additional decisions become Normal. Every V label stays identical, with macro-F1 97.8800\%, Normal FPR 36/3,860 (0.9326\%), two missed attacks, SQL recall 99.6973\% and ransomware recall 95.3143\%. Table S59 retains the unchanged confusion matrix. The seed-42 value is distinct from the 97.8954\% three-seed mean.
'''+gt+r'''
The agreement with RF-only is decisive for interpretation: the observed reduction is attributable to resolving the known RF/voting conflicts, not a demonstrated unique benefit of syntax or TF-IDF. Payload checks can retain an alarm when they find SQL evidence, but no evaluated attack tests that protection in the conflict region. There are zero eligible disagreements among 5,360 G, 5,190 C and 10,358 V targets. All 321 activations belong to the additional Normal sources, and only 64 have usable content (Table S58). Unchanged V predictions are therefore an empirical observation outside the activated region, not a non-inferiority or future sensitivity guarantee. Figure~\ref{fig:repair} makes this separate predictor path explicit.

\begin{figure}[!htbp]\centering\includegraphics[width=\linewidth]{figures/fpr_reconciliation.pdf}\caption{Post-observation selective output rule. The original voting posterior is retained unless the SQL/Normal conflict and RF confidence conditions hold and usable content does not retain SQL. A replacement uses the full RF posterior. This rule changes the predictor; the compact-execution certificate and archived explanation-equivalence results apply to the original voting function, not automatically to this path.}\label{fig:repair}\end{figure}

Table~\ref{tab:repair_cost} reports the associated cost in a separate native session. On additional760, median batch time rises from 41.675 ms to 61.109 ms with the hybrid guard (+46.63\%) and to 42.664 ms with RF-only (+2.37\%). No original compact-replay saving is claimed for the guard. RF-only matches the observed alarm reduction at lower measured cost; a unique safety benefit from the additional content model remains untested. The same-corpus, correlated targets, 107 unscorable candidates and absence of independent conflict attacks continue to limit all zero-alarm outcomes.
'''+ct
    anchor=r'\section{Prototype and reproducibility}';assert anchor in maintex;maintex=maintex.replace(anchor,results+'\n'+anchor,1)
    anchor=r'\section{Discussion and limitations}'
    cli=r'''A separate command-line prototype evaluates the new disagreement rule on prepared C60/O10 feature rows and aligned hexadecimal payload fields. It checks row identities and model/catalog hashes before using the owned fitted artifacts, emits a normalized five-class posterior, and refuses to overwrite an existing result. It does not modify the dashboard or make its saved explanations valid for changed decisions. Nineteen targeted software tests and independent reconstruction of the saved metrics pass; extraction to a separate root reproduces the example predictions without refitting a classifier.

'''
    assert anchor in maintex;maintex=maintex.replace(anchor,cli+anchor,1)
    anchor='A fully aligned independent test with both normal and attack sources and a frozen pipeline is still needed for a general detection claim.'
    assert anchor in maintex;maintex=maintex.replace(anchor,'Matched payload refits do not resolve this failure. The selective RF rule removes the 321 observed alarms, but RF-only matches it and no attack activates the rule on G/C/V. Its conditional zero rate is therefore a retrospective diagnostic result, with no demonstrated unique TF-IDF benefit or non-inferiority in the conflict region. '+anchor,1)
    anchor='Full-probability implementation equivalence and explanation quality are separate properties.'
    assert anchor in maintex;maintex=maintex.replace(anchor,anchor+' The payload/RF rule changes output probabilities, so reference SHAP games and their preservation checks cannot be reused as explanations of changed guard decisions.',1)
    anchor='Encoded-space SMOTE and synthetic packet/history hybrids introduce further modelling assumptions.'
    assert anchor in maintex;maintex=maintex.replace(anchor,'The 5 November rule responds directly to known additional-source failures, despite retaining fixed operational thresholds; no prospective final test is available. Binary content labels also coincide with different protocol/capture types. '+anchor,1)
    old='Context helps within the observed temporal traces, but these controls preclude interpreting that gain as reliable source-independent detection.'
    new=r'''Matched full-A payload refits leave 310--331 additional alarms and raise attack-to-Normal errors from two to three or four. A separate post-observation RF/payload rule reduces the observed additional alarms to 0/760 and leaves all 10,358 V labels unchanged, but RF-only gives the same reduction. No attack in G/C/V activates the rule, so unchanged V sensitivity does not validate its conflict region. Context helps within the observed temporal traces; neither the original gain nor the conditional zero-alarm repair establishes reliable source-independent detection.'''
    assert old in maintex;maintex=maintex.replace(old,new,1)
    anchor='This is an implementation-specific result on one laptop and a replay with 160 annotated decisions, not a hardware-independent speed guarantee.'
    assert anchor in maintex;maintex=maintex.replace(anchor,anchor+' The separate hybrid-rule batch benchmark is slower than its native reference (61.109 versus 41.675 ms on additional760); its cost is not covered by the original execution saving.',1)
