    highlights=['Matched controls isolate a 1.14-point within-trace temporal F1 gain.','Payload refits retain high FPR; selective RF checks remove observed benign alarms.','Zero guard attack activations limit claims about detection safety.','Compact execution of the reference saves 41.75% mean replay time.','Window-level donor games audit explanation faithfulness and consistency.']
    assert all(len(s)<=85 for s in highlights);(NEW/'highlights.txt').write_text('\n'.join(highlights)+'\n',encoding='utf8')
