    def st(label,caption,header,data,weights,note):return table('sup:'+label,caption,header,data,weights,note)
    additions+=st('repair_design','Cohorts, fit budgets and operational defaults for the payload investigation.',['Item','Recorded design'],[
        ['Five-class A / G / C / V','31,676 / 5,360 / 5,190 / 10,358; original seed-42 roles'],['Historical holdout','13,171 identifiers excluded from new fits and predictive scoring'],['Additional Normal','760 matched targets; 107 eligible candidates remain unscorable'],['Binary A','100 unique nonempty contents per class; 200 total'],['Binary V primary','1,012 unseen nonempty content hashes: 895 Normal, 117 SQL'],['Binary V all / nonempty','5,512 / 1,143; repeated content excluded only from primary subset'],['Binary additional nonempty','215/760; separate conditional diagnostic'],['New classifier fits','48 binary including OOF/meta; 20 full-A expert fits; no guard fits'],['Resampling','RUS then SMOTE, training only; synthetic/class <=0.5 before RUS'],['Seeds / thread count','Binary selection20261105; OOF59; estimator42; one numerical thread'],['Guard threshold','RF Normal >=0.5; fixed operational default, not calibrated']],[.31,.69],r'Role counts are target counts after temporal purging. V is reused development, not an untouched test. No current experiment adds traffic captures, learner families or generated payload text.')
    features=[['Single quote / OR / equals','Counts in lowercase decoded content'],['Numeric tautology','Presence of a numeric equality pattern with OR/AND'],['UNION SELECT','Presence of the explicit UNION followed by SELECT pattern'],['isdecimal','Indicator that the complete extracted text is decimal'],['Double quote / AND','Counts of double quotes and AND words'],['Line / block comments','Counts of -- plus hash comments, and /* openers'],['Semicolon / SQL keywords','Semicolon count and fixed SQL-keyword count'],['Character TF-IDF','2--5 grams; max2048; min_df1; lowercase; sublinear TF; L2'],['Current content bound','4,096 bytes; query/form values decoded once; no Host/Cookie/IP'],['Normal binary training','50 MQTT bodies +50 other TCP contents'],['SQL binary training','100 HTTP request query values']]
    additions+=st('repair_content','Syntax components, character representation and binary content composition.',['Component','Definition / count'],features,[.34,.66],r'The first six indicators preserve the original syntax example; the expanded representation has twelve fields. Numeric-tautology matching is exactly the supplied implementation, not a semantic SQL parser. Complete regexes and 200 escaped training examples are in the archive. TF-IDF vocabulary/IDF and scaler fitting are training-only. Protocol/source confounding remains between Normal and SQL.')
    data=[]
